@js:(function(){
  var UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/134.0.0.0 Safari/537.36';
  var s = String((typeof java !== 'undefined' && java.baseUrl) || (typeof baseUrl !== 'undefined' ? baseUrl : '') || '');
  var m = s.match(/trackId=([^&]+)/);
  if (!m) { var m2 = s.match(/\/song\/(\d+)/); if (m2) m = m2; }
  if (!m || !m[1]) return '';
  var tid = m[1];
  try {
    // 第一步: H5 SEO 接口拿播放信息页
    var seoUrl = 'https://beta-luna.douyin.com/luna/h5/seo_track?track_id=' + tid + '&device_platform=web';
    var seoOpt = { headers: { 'User-Agent': UA, 'Referer': 'https://www.douyin.com/' } };
    var seo = java.ajax(seoUrl + ',' + JSON.stringify(seoOpt));
    if (!seo) return '';
    var sj = JSON.parse(seo);
    var pu = (sj.track_player && sj.track_player.url_player_info) || '';
    if (!pu) return '';
    // 第二步: 播放信息页拿真实音频地址
    var puOpt = { headers: { 'User-Agent': UA, 'Referer': 'https://www.douyin.com/' } };
    var info = java.ajax(pu + ',' + JSON.stringify(puOpt));
    if (!info) return '';
    var ij = JSON.parse(info);
    var pl = (ij.Result && ij.Result.Data && ij.Result.Data.PlayInfoList) || [];

    function val(q) {
      q = String(q || '').toLowerCase();
      if (q.indexOf('highest') >= 0 || q === 'hi' || q === 'exhigh') return 4;
      if (q.indexOf('higher') >= 0 || q === 'sq' || q === 'lossless') return 3;
      if (q.indexOf('normal') >= 0 || q === 'hq') return 2;
      if (q === 'lq' || q.indexOf('low') >= 0) return 1;
      return 0;
    }
    var best = '', bestV = -1;
    for (var i = 0; i < pl.length; i++) {
      var u = pl[i].MainPlayUrl || pl[i].BackupPlayUrl1 || pl[i].BackupPlayUrl2 || '';
      if (!u) continue;
      var v = val(pl[i].Quality || pl[i].QualityDesc || '');
      if (v > bestV) { bestV = v; best = u; }
    }
    if (!best && pl.length) best = pl[0].MainPlayUrl || pl[0].BackupPlayUrl1 || '';
    return best || '';
  } catch (e) { return ''; }
})()

