  try {
    var j = (typeof result === 'string') ? JSON.parse(result) : result;
    if (!j) return [];
    var out = [];
    var items = j.items || j.data || [];
    for (var i=0; i<items.length; i++) {
      var ent = items[i].entity || items[i];
      var tr = ent.track_wrapper && ent.track_wrapper.track || ent.track || ent.audio || ent;
      if (!tr || !tr.id) continue;
      var album = tr.album || {};
      var arts = tr.artists || [];
      var an = []; for (var a=0; a<arts.length; a++) an.push(arts[a].name||'');
      var uc = album.url_cover || album.cover || {};
      var list = uc.urls || uc.url_list || [];
      var cov = (list && list.length) ? (list[0] + (uc.uri||'')) : '';
      out.push({
        name: tr.name || '',
        author: an.join('/'),
        coverUrl: cov,
        detail: 'https://www.qishui.com/song/' + tr.id + '?trackId=' + tr.id,
        lastChapter: '时长' + Math.round((tr.duration||0)/1000) + '秒'
      });
    }
    return out;
  } catch (e) { return []; }
})()

