@js:(function(){
  try {
    var j = (typeof result === 'string') ? JSON.parse(result) : result;
    if (!j) return [];
    var out = [];
    // 结构A(主): result_groups[].data[].entity.track
    var groups = j.result_groups || [];
    for (var g=0; g<groups.length; g++) {
      var datas = (groups[g] && groups[g].data) || [];
      for (var i=0; i<datas.length; i++) {
        var tr = pickTrack(datas[i]);
        if (tr) out.push(mkItem(tr));
      }
    }
    // 结构B(兜底): items[].entity.track / 直接 data[]
    if (!out.length) {
      var arr = j.items || j.data || j.tracks || [];
      for (var k=0; k<arr.length; k++) {
        var tr2 = pickTrack(arr[k]);
        if (tr2) out.push(mkItem(tr2));
      }
    }
    return out;
  } catch (e) { return []; }

  function pickTrack(node) {
    if (!node) return null;
    var ent = node.entity || node;
    var tr = ent.track || ent.audio || ent.track_wrapper && ent.track_wrapper.track || ent;
    return (tr && tr.id) ? tr : null;
  }
  function mkItem(tr) {
    var album = tr.album || {};
    var arts = tr.artists || [];
    var an = []; for (var a=0; a<arts.length; a++) an.push(arts[a].name||'');
    return {
      name: tr.name || '',
      author: an.join('/'),
      coverUrl: coverOf(album),
      detail: 'https://www.qishui.com/song/' + tr.id + '?trackId=' + tr.id,
      lastChapter: '时长' + Math.round((tr.duration||0)/1000) + '秒'
    };
  }
  function coverOf(album) {
    var uc = album.url_cover || album.cover || {};
    var list = uc.urls || uc.url_list || [];
    if (list && list.length) return list[0] + (uc.uri || '');
    var uc2 = album.url_cover || {};
    if (uc2.url_list && uc2.url_list.length) return uc2.url_list[0];
    return '';
  }
})()

